+//!
+//! 归属: Fatal 递增阶梯 [`cooldown_duration_ms`] 与 429 独立阶梯
+//! `throttle_cooldown_duration_ms`（幂律形状，共享私有 `SHAPE_EXPONENT`），
+//! 以及冷却进出（`start_cooldown` / `finish_cooldown`）与空闲退火
+//! `anneal_streak`。outcome 侧的记账在 [`outcome`] 子模块。
+
+use super::outcome::{ChannelOutcome, THROTTLE_RAMP_STEPS, UNAUTHORIZED_ESCALATION_THRESHOLD};
+use super::{HealthSetting, HealthState};
+
+/// 冷却阶梯的形状指数 `p`（见 [`cooldown_duration_ms`]）。
+///
+/// `p > 1` 凸 = 起步缓、后期陡（先慢后快）；`p < 1` 凹 = 起步陡。取 2.0：
+/// 在 base=300ms / max=8s / N=12 下首步仅 53ms（base 的 18%）——亚秒起步
+/// 要求"第一次失败几乎不惩罚"，幂律是能做到这一点的最简形式。
+const SHAPE_EXPONENT: f64 = 2.0;
+
+/// 冷却时长按连击次数递增，逼近 `cooldown_max_ms` 天花板。base/max 同为毫秒。
+///
+/// ```text
+/// 时长(n) = min(max_ms, base_ms + (max_ms - base_ms) × (n/N)^p)
+/// 其中      N = cooldown_ramp_steps，p = SHAPE_EXPONENT
+/// ```
+///
+/// **为什么用幂律**：`p = 2` 时函数严格凸 —— 正向走（连击累积）步长递增，
+/// 先慢后快；反向走（`anneal_streak` 把 streak 逐窗递减）沿同一条曲线回退，
+/// 步长递减 —— 先快后慢。**一个公式同时满足两个方向**，不需要为恢复单写
+/// 一套衰减律。
+///
+/// **为什么不用 tan**：tan 的 `φ(n) = n·π/(2N)` 用同一个 `N` 同时决定早期
+/// 斜率与触顶位置 —— 想放缓起步就得放大 `N`，但 `N` 一放大触顶点也跟着后推
+/// （N=40 时要 20 级才封顶，且前 9 步步长几乎恒定，凸性被摊平成直线）。
+/// 幂律把**形状（p）与视野（N）解耦**：p 单独控制起步有多缓，N 单独控制
+/// 多少级封顶。
+///
+/// 默认阶梯（300ms → 8s, N=12, p=2）：0.35 → 0.51 → 0.78 → 1.16 → 1.64 →
+/// 2.23 → 2.92 → 3.72 → 4.63 → 5.65 → 6.77 → 8.00s，步长
+/// 53 / 160 / 267 / 374 / 481 / 588 / 695 / 802 / 909 / 1016 / 1123 / 1230ms
+/// 严格递增。对照 tan(N=12) 首步 1277ms（占 base 的 426%，旧 10s 天花板口径），
+/// 幂律首步仅 53ms（18%）。
+///
+/// `n ≥ N` 时 `(n/N)^p ≥ 1` 被 `min(max, …)` 夹住，故冷却时长恒 ≤ `max`。
+pub(super) fn cooldown_duration_ms(cfg: &HealthSetting, streak: u32) -> u64 {
+    let base = cfg.cooldown_base_ms;
+    let max = cfg.cooldown_max_ms;
+    if base == 0 || max == 0 || max <= base {
+        return base;
+    }
+    let steps = cfg.cooldown_ramp_steps.max(1) as f64;
+    let n = (streak as f64).min(steps).max(0.0);
+    let ramp = (n / steps).powf(SHAPE_EXPONENT);
+    (base as f64 + (max - base) as f64 * ramp).clamp(base as f64, max as f64) as u64
+}
+
+/// 429 独立阶梯 — 冷却时长按 `throttle_streak` 递增，逼近
+/// `throttle_max_ms` 天花板（与 Fatal 的 `cooldown_max_ms` 解耦）。
+///
+/// ```text
+/// 时长(n) = min(throttle_max_ms,
+///              cooldown_base_ms + (throttle_max_ms - cooldown_base_ms)
+///              × (n/THROTTLE_RAMP_STEPS)^p)   p = SHAPE_EXPONENT
+/// ```
+///
+/// 与 [`cooldown_duration_ms`] 同形（复用幂律与 `SHAPE_EXPONENT`），但视野
+/// 固定 `THROTTLE_RAMP_STEPS` = 4 级触顶——429 是暂态限流，阶梯短而陡，
+/// 默认 300ms → 1s 下阶梯 343 → 475 → 693 → 1000ms（截断取整）。`n ≥ N` 时
+/// `(n/N)^p ≥ 1` 被夹住，时长恒 ≤ `throttle_max_ms`。
+pub fn throttle_cooldown_duration_ms(cfg: &HealthSetting, streak: u32) -> u64 {
+    let base = cfg.cooldown_base_ms;
+    let max = cfg.throttle_max_ms;
+    if base == 0 || max == 0 || max <= base {
+        return base;
+    }
+    let steps = f64::from(THROTTLE_RAMP_STEPS.max(1));
+    let n = (streak as f64).min(steps).max(0.0);
+    let ramp = (n / steps).powf(SHAPE_EXPONENT);
+    (base as f64 + (max - base) as f64 * ramp).clamp(base as f64, max as f64) as u64
+}
+
+/// 进入冷却，并把所有 outcome 分档统一封顶到 `cooldown_max_ms`。
+///
+/// 401/403 连续升级、其它致命失败走 Fatal 阶梯（`cooldown_streak` →
+/// [`cooldown_duration_ms`]）；429 走独立阶梯（`throttle_streak` →
+/// [`throttle_cooldown_duration_ms`]），Retry-After hint 有则直接覆盖阶梯
+/// （clamp 到 `cooldown_max_ms`）。任何一次冷却都不会超过配置上限。
+pub(super) fn start_cooldown(
+    st: &mut HealthState,
+    cfg: &HealthSetting,
+    now_ms: u64,
+    outcome: ChannelOutcome,
+    retry_after_ms: Option<u64>,
+) {
+    let max_ms = cfg.cooldown_max_ms;
+    let requested_ms = match outcome {
+        ChannelOutcome::Fatal if st.unauthorized_run >= UNAUTHORIZED_ESCALATION_THRESHOLD => {
+            st.cooldown_streak += 1;
+            max_ms
+        }
+        ChannelOutcome::Throttled => {
+            // 429 是上游主动限流, 不是渠道故障: 独立阶梯 343→475→693→1000ms
+            // （默认范围）, 不写 cooldown_streak。Retry-After 有 hint 时
+            // 直接覆盖阶梯 —— 上游知道该等多久，比本地估算更准。
+            st.throttle_streak += 1;
+            let ladder_ms = throttle_cooldown_duration_ms(cfg, st.throttle_streak);
+            match retry_after_ms {
+                Some(hint_ms) => hint_ms.min(max_ms),
+                None => ladder_ms,
+            }
+        }
+        _ => {
+            // 先用当前 streak 取档再递增：首败 = rung 0 = base，
+            // 与幂律阶梯文档口径一致（第 k 次失败落在 rung k-1）。
+            let ladder_ms = cooldown_duration_ms(cfg, st.cooldown_streak);
+            st.cooldown_streak += 1;
+            ladder_ms
+        }
+    };
+    let d = requested_ms.min(max_ms);
+    if d == 0 {
+        return;
+    }
+    st.last_cooling_outcome = Some(outcome);
+    st.request_count = 0;
+    st.ramp_exited = false;
+    st.cooldown_until_ms = now_ms + d;
+}
+
+/// 结束冷却 — phase0 `finishCooldownLocked`: 清除冷却, 武装 slow-start ramp。
+/// `now_ms` 记为退火起点: 之后若持续空闲, 双连击账本按 base 窗口同构衰减。
+pub(super) fn finish_cooldown(st: &mut HealthState, now_ms: u64) {
+    st.cooldown_until_ms = 0;
+    st.request_count = 0;
+    st.ramp_exited = false;
+    st.ramp_pending = true;
+    st.anneal_since_ms = now_ms;
+}
+
+/// 空闲退火 — 冷却到期后若持续无流量, `cooldown_streak` 与 `throttle_streak`
+/// 随时间同构线性回落（复用同一 base 窗口，不加新配置）。
+///
+/// 退火窗口复用 `cooldown_base_ms`: 每过一个完整窗口 两账本各 -1
+/// (saturating 到 0), 零头留给下一次结算。活跃流量本身会经
+/// apply_outcome 的 Success 分支递减双账本并清零锚点, 所以退火只管"静默"
+/// 的渠道; 锚点为 0 (成功过) 时休眠, 直到下一次冷却结束重新设锚。
+///
+/// - `st`: 待结算状态, 原地衰减;
+/// - `cfg`: 提供退火窗口时长;
+/// - `now_ms`: 当前时钟。
+///
+/// 仅在读取路径 (is_selectable) 惰性调用 —— record 本身
+/// 就是活跃事件, 不需要退火。
+pub(super) fn anneal_streak(st: &mut HealthState, cfg: &HealthSetting, now_ms: u64) {
+    if st.cooldown_until_ms != 0
+        || st.anneal_since_ms == 0
+        || (st.cooldown_streak == 0 && st.throttle_streak == 0)
+    {
+        return;
+    }
+    let window_ms = cfg.cooldown_base_ms;
+    if window_ms == 0 {
+        return;
+    }
+    let steps = now_ms.saturating_sub(st.anneal_since_ms) / window_ms;
+    if steps == 0 {
+        return;
+    }
+    st.cooldown_streak = st.cooldown_streak.saturating_sub(steps as u32);
+    st.throttle_streak = st.throttle_streak.saturating_sub(steps as u32);
+    st.anneal_since_ms += steps * window_ms;
+    if st.cooldown_streak == 0 && st.throttle_streak == 0 {
+        st.anneal_since_ms = 0;
+    }
+}
