@@ -0,0 +1,237 @@
+//! outcome 分类与记账 — 母模块 `health` 的 outcome 子模块（step 4 拆分，逻辑逐字不变）。
+//!
+//! 归属: [`FailureClass`] / [`ChannelOutcome`] / [`TpsSample`] / [`AttemptReport`]
+//! 四个载荷类型 + 其常量，以及 `classify`（状态码 → outcome，含 401/403 连续
+//! 升级）与 `apply_outcome`（记账入口：EWMA 观测、冷却、slow-start）。
+//! 阶梯时长本身在 [`cooldown`] 子模块。
+
+use super::cooldown::{finish_cooldown, start_cooldown};
+use super::{HealthSetting, HealthState, age_ewma_score};
+
+/// 可重试错误分类 — 决定状态机是否回退换下一个候选。
+/// 健康分类独立于重试决策: 健康看上游状态码, 重试看客户端可恢复性。
+#[derive(Debug, Clone, Copy, PartialEq, Eq)]
+pub enum FailureClass {
+    /// 传输层失败 (超时/连接) → 换候选重试。
+    Retryable,
+    /// 客户端或凭据问题 (4xx) → 不重试。
+    Fatal,
+}
+
+/// 健康 outcome — phase0 `ChannelOutcome` 枚举。
+#[derive(Debug, Clone, Copy, PartialEq, Eq)]
+pub enum ChannelOutcome {
+    /// 2xx — 全信任, EWMA obs = 1.0。
+    Success,
+    /// 5xx / 传输层 / 坏 body — 记 streak, obs = 0.0, 触发冷却。
+    Fatal,
+    /// 429 — 渠道健康但被限流, 轻度降权, obs = 0.7。
+    Throttled,
+    /// 其它 4xx (400/404/422/孤立 401/403) — 渠道无责, 不改分不记 streak。
+    Neutral,
+}
+
+impl ChannelOutcome {
+    /// 是否影响 EWMA 分数 (Success/Fatal/Throttled; Neutral 不参与)。
+    pub fn affects_health(self) -> bool {
+        !matches!(self, ChannelOutcome::Neutral)
+    }
+}
+
+/// 429 的 EWMA 观测值 (轻度降权, 非致命)。
+pub const THROTTLED_OBSERVATION: f64 = 0.7;
+/// 连续 401/403 达此数升级为 Fatal。
+pub const UNAUTHORIZED_ESCALATION_THRESHOLD: u32 = 3;
+/// 无历史渠道的默认分。
+pub const DEFAULT_SCORE: f64 = 1.0;
+
+/// 429 独立阶梯的视野 N（级数）：第 N 次连续 429 触到 `throttle_max_ms`
+/// （见 [`throttle_cooldown_duration_ms`](super::cooldown::throttle_cooldown_duration_ms)）。429 是暂态限流，阶梯刻意短而陡：
+/// 固定 4 级触顶（不设配置口）——比 Fatal 曲线 (N=12) 少两级视野，避免
+/// 持续被限流的渠道在健康表里烧出长冷却；Retry-After hint 覆盖才是
+/// 429 时长的主要手段。
+pub const THROTTLE_RAMP_STEPS: u32 = 4;
+
+/// tps EMA 平滑系数 — 按来源分档：实测样本 0.2（主 EMA），估算兜底样本
+/// 0.1（噪声隔离，见设计 §3.2：「无 usage 的估算兜底样本：更新但 α 减半」）。
+pub const TPS_ALPHA_MEASURED: f64 = 0.2;
+pub const TPS_ALPHA_ESTIMATED: f64 = 0.1;
+
+/// 生成吞吐样本（tok/s）— 渠道级 EMA 的输入。
+///
+/// 校验（`>= 0.0`、非有限值归零）由 forward 侧计算点负责，本枚举不做
+/// 数值校验——它只区分两类来源，EMA 按来源取不同的 α：
+/// - [`Measured`](TpsSample::Measured): 正常流式完成的实测吞吐
+///   （`completion_tokens / 生成段耗时`），α = 0.2；
+/// - [`Estimated`](TpsSample::Estimated): 无 usage 的估算兜底样本（bytes/4），
+///   噪声更大，α = 0.1 与主 EMA 隔离。
+#[derive(Debug, Clone, Copy, PartialEq)]
+pub enum TpsSample {
+    Measured(f64),
+    Estimated(f64),
+}
+
+/// 一次尝试的健康回报载荷 — `HealthTable::record` / `Dispatch::report` 的
+/// 统一结构体（旧四参切断后不再撕裂 trait 与 mock）。
+#[derive(Debug, Clone, Copy)]
+pub struct AttemptReport {
+    /// `Ok(status)` 按状态码分类；`Err(FailureClass)` 传输层/客户端失败。
+    pub outcome: Result<u16, FailureClass>,
+    /// 本次尝试的上游往返耗时（ms）；失败或无观测 = `None`。
+    pub latency_ms: Option<u32>,
+    /// 上游 429 `Retry-After` hint（ms）；仅 Throttled 语义有效，其余丢弃。
+    pub retry_after_ms: Option<u64>,
+    /// 生成吞吐样本（tok/s）；非流式 / 断流 / 未计算 = `None`。
+    pub tps: Option<TpsSample>,
+}
+
+impl AttemptReport {
+    /// 构造基础回报（`tps` 缺省 `None`）；需要带吞吐样本时链
+    /// [`with_tps`](AttemptReport::with_tps) builder。
+    pub fn new(
+        outcome: Result<u16, FailureClass>,
+        latency_ms: Option<u32>,
+        retry_after_ms: Option<u64>,
+    ) -> Self {
+        Self {
+            outcome,
+            latency_ms,
+            retry_after_ms,
+            tps: None,
+        }
+    }
+
+    /// 附带生成吞吐样本（消费 `self`，返回带 tps 的新值）。
+    pub fn with_tps(mut self, sample: TpsSample) -> Self {
+        self.tps = Some(sample);
+        self
+    }
+}
+
+/// 按结果分类并记账，保持现有 outcome、健康分、冷却与 slow-start 语义。
+/// `retry_after_ms`: 上游 429 `Retry-After` hint (ms) — 仅 outcome 分类为
+/// Throttled 时传给冷却阶梯做覆盖（clamp 到 `cooldown_max_ms`），
+/// 其它 outcome 丢弃。
+pub(super) fn apply_outcome(
+    st: &mut HealthState,
+    outcome: Result<u16, FailureClass>,
+    cfg: &HealthSetting,
+    now_ms: u64,
+    retry_after_ms: Option<u64>,
+) {
+    if !cfg.enabled {
+        return;
+    }
+
+    // 先结算过期冷却 (post-expiry 结果干净地重入 slow-start ramp)。
+    if st.cooldown_until_ms != 0 && !st.is_cooling(now_ms) {
+        finish_cooldown(st, now_ms);
+    }
+
+    let outcome = classify(st, outcome);
+
+    match outcome {
+        ChannelOutcome::Success => {
+            // 活跃事件重新计期: 退火锚点清零, 空闲窗口从头算。
+            st.anneal_since_ms = 0;
+            // 冷却过期后的干净成功递减冷却连击 (下次失败从更短时长起步)。
+            if st.cooldown_streak > 0 && st.cooldown_until_ms == 0 {
+                st.cooldown_streak = st.cooldown_streak.saturating_sub(1);
+            }
+            // 429 独立账本同构递减: 成功证明限流已缓解。
+            if st.throttle_streak > 0 && st.cooldown_until_ms == 0 {
+                st.throttle_streak = st.throttle_streak.saturating_sub(1);
+            }
+        }
+        // Neutral (400/404/孤立 401): 渠道无责 —— 不改分、不计请求、
+        // 不进冷却, 原样早退。
+        ChannelOutcome::Neutral => return,
+        // Fatal / Throttled 的惩罚全部由下方 start_cooldown 承担,
+        // 这里不再需要任何累计计数。
+        ChannelOutcome::Fatal | ChannelOutcome::Throttled => {}
+    }
+
+    // EWMA 观测值。
+    let observation = match outcome {
+        ChannelOutcome::Success => 1.0,
+        ChannelOutcome::Fatal => 0.0,
+        ChannelOutcome::Throttled => THROTTLED_OBSERVATION,
+        ChannelOutcome::Neutral => unreachable!("Neutral returned above"),
+    };
+
+    st.request_count += 1;
+    st.ramp_pending = false;
+
+    // 真实失败立即退出 ramp。
+    if outcome == ChannelOutcome::Fatal {
+        st.ramp_exited = true;
+    }
+
+    // MinRequests 前不更新 EWMA (信任新渠道)。
+    if st.request_count > cfg.min_requests {
+        // 更新前按 Δt 向默认分老化 (score_decay_tau_ms 时间常数):
+        // 闲置渠道的旧惩罚随时间失效，半衰期 T½ = τ·ln2。
+        let prior = age_ewma_score(st, cfg, now_ms);
+        st.ewma_score = cfg.alpha * observation + (1.0 - cfg.alpha) * prior;
+        if st.ewma_score < cfg.min_score {
+            st.ewma_score = cfg.min_score;
+        }
+        st.score_updated_at_ms = now_ms;
+    }
+
+    // 任何一次 fatal/throttled 立即进冷却 —— 不再攒「连续 N 次」的门槛。
+    // 惩罚强度全部由 `cooldown_duration_ms` 的阶梯承担 (300ms → 8s)：
+    // 首次失败只被摘 300ms (快回来)，连击才把时长拉长。门槛若保留，
+    // 攒够次数的那段窗口里坏渠道仍在吃流量，且重试因 mark_tried 保证
+    // 同请求内不复选同一 unit，永远观测不到「持续失败」——该窗口无人补位。
+    if matches!(outcome, ChannelOutcome::Fatal | ChannelOutcome::Throttled) {
+        start_cooldown(st, cfg, now_ms, outcome, retry_after_ms);
+    }
+}
+
+/// 分类 — phase0 `classifyChannelOutcomeUnlocked` + UnauthorizedRun 升级。
+

